create or replace trigger apx_mbms_job_orders_trg
before insert or update on apx_mbms_job_orders
for each row
begin
   if inserting then
      if not apx_mbms_approval_pkg.bypass then
         :new.status := 'DRAFT';
      end if;
      if :new.job_no is null then
         :new.job_no := apx_mbms_doc_pkg.next_no('JO');
      end if;
   elsif not apx_mbms_approval_pkg.bypass then
      if :old.status = 'SUBMITTED' then
         raise_application_error(-20110, 'Job Order ' || :old.job_no || ' sedang menunggu approval dan tidak dapat diubah.');
      end if;
      if :old.status in ('CANCELLED', 'CLOSED') then
         raise_application_error(-20111, 'Job Order ' || :old.job_no || ' sudah ' || :old.status || '.');
      end if;
      if :new.status <> :old.status
         and not (:old.status in ('APPROVED', 'IN_PROGRESS', 'COMPLETED', 'CLOSED') and :new.status in ('IN_PROGRESS', 'COMPLETED', 'CLOSED'))
      then
         raise_application_error(-20112, 'Perubahan status ' || :old.status || ' -> ' || :new.status || ' tidak diizinkan. Gunakan Submit for Approval.');
      end if;
      -- kolom terkunci setelah approval (BR change management)
      if :old.status not in ('DRAFT', 'REJECTED') then
         :new.job_type := :old.job_type;
         :new.customer_id := :old.customer_id;
         :new.product_desc := :old.product_desc;
         :new.qty_order := :old.qty_order;
         :new.ups_per_sheet := :old.ups_per_sheet;
         :new.insheet_pct := :old.insheet_pct;
         :new.selling_price := :old.selling_price;
         :new.est_paper := :old.est_paper;
         :new.est_ink := :old.est_ink;
         :new.est_plate := :old.est_plate;
         :new.est_machine := :old.est_machine;
         :new.est_finishing := :old.est_finishing;
         :new.est_labor := :old.est_labor;
         :new.est_overhead := :old.est_overhead;
      end if;
   end if;
   if inserting then
      :new.created_by := apx_mbms_sec_pkg.app_user;
      :new.created_on := sysdate;
   end if;
   :new.updated_by := apx_mbms_sec_pkg.app_user;
   :new.updated_on := sysdate;
end;
/

