create or replace trigger apx_mbms_wbs_trg
before insert or update or delete on apx_mbms_wbs
for each row
declare
   l_parent_status varchar2(30);
   e_mutating      exception;
   pragma exception_init(e_mutating, -4091);
begin
   begin
      select status
        into l_parent_status
        from apx_mbms_projects
       where project_id = coalesce(:new.project_id, :old.project_id);
   exception
      when e_mutating then
         return; -- delete cascade dari apx_mbms_projects
   end;
   if not apx_mbms_approval_pkg.bypass and l_parent_status not in ('DRAFT', 'REJECTED') then
      raise_application_error(-20121, 'WBS Budget tidak dapat diubah karena Project berstatus ' || l_parent_status || '.');
   end if;
   if deleting then
      return;
   end if;
   :new.wbs_code := upper(:new.wbs_code);
   if inserting then
      :new.created_by := apx_mbms_sec_pkg.app_user;
      :new.created_on := sysdate;
   end if;
   :new.updated_by := apx_mbms_sec_pkg.app_user;
   :new.updated_on := sysdate;
end;
/

